WITH valid_accounts AS (SELECT *, CONCAT(account_type, '/', status) AS account_type_status FROM accounts WHERE opened_date BETWEEN '2023-12-20' AND '2024-03-01' AND customer_id IS NULL), status_summary AS (SELECT status, ROUND((100 * SUM(CASE WHEN status = 'FROZEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_frozen, COUNT(balance) AS balance_count FROM valid_accounts GROUP BY status) SELECT status, balance_count FROM status_summary WHERE pct_frozen < 72
